static void require(bool value,const std::string &why){if(!value)throw std::runtime_error(why);}
static id<MTLTexture> texture(id<MTLDevice> device,MTLPixelFormat format,unsigned width,unsigned height){auto d=[MTLTextureDescriptor texture2DDescriptorWithPixelFormat:format width:width height:height mipmapped:NO];d.storageMode=MTLStorageModeShared;d.usage=MTLTextureUsageShaderRead|MTLTextureUsageShaderWrite|MTLTextureUsageRenderTarget;return [device newTextureWithDescriptor:d];}
static void wait(id<MTLCommandBuffer> commands){auto done=dispatch_semaphore_create(0);[commands addCompletedHandler:^(id<MTLCommandBuffer>){dispatch_semaphore_signal(done);}];[commands commit];require(!dispatch_semaphore_wait(done,dispatch_time(DISPATCH_TIME_NOW,10*NSEC_PER_SEC)),"Temporal GPU deadline");require(commands.status==MTLCommandBufferStatusCompleted,commands.error.localizedDescription.UTF8String?:"Temporal GPU failure");}
