    auto scaler=[descriptor newTemporalScalerWithDevice:device];require(scaler!=nil,"Cannot create original temporal scaler");scaler.colorTexture=color;scaler.depthTexture=depth;scaler.motionTexture=motion;scaler.inputContentWidth=64;scaler.inputContentHeight=48;scaler.preExposure=1;scaler.motionVectorScaleX=1;scaler.motionVectorScaleY=1;scaler.reset=YES;
